ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  status: "ok",
  sizesSentBytes: {
    small: sizeOf(vars.smallMessage as Binary {encoding: "UTF-8"}),
    medium: sizeOf(vars.mediumMessage as Binary {encoding: "UTF-8"}),
    large: sizeOf(vars.largeMessage as Binary {encoding: "UTF-8"})
  }
}
